    /**
     * @param $qb
     * @param $data
     */
    protected function apiHandleSearchBetween($qb,$data)
    {

        $startDate      = (isset($data['start_date']) and $data['start_date']) ? $data['start_date']:'';
        $endDate        = (isset($data['end_date']) and $data['end_date']) ? $data['end_date']:'';
        $toUser         = (isset($data['to_user_id']) and $data['to_user_id']) ? $data['to_user_id'] :'';
        $user           = (isset($data['user_id']) and $data['user_id'])? $data['user_id'] :'';
        $keyword        = (isset($data['keyword']) and $data['keyword']) ? $data['keyword'] :'';
        $accountHead    = (isset($data['account_head_id']) and $data['account_head_id']) ? $data['account_head_id'] :'';
        $category       = (isset($data['category_id']) and $data['category_id']) ? $data['category_id'] :'';
        $customer       = (isset($data['customer_id']) and $data['customer_id']) ? $data['customer_id'] :'';
        $vendor         = (isset($data['vendor_id']) and $data['vendor_id']) ? $data['vendor_id'] :'';

        if(!empty($startDate) and !empty($endDate)){
            $start = new \DateTime($startDate);
            $startDate = $start->format('Y-m-d 00:00:00');
            $end = new \DateTime($endDate);
            $endDate = $end->format('Y-m-d 23:59:59');
            $qb->andWhere("e.created >= :startDate");
            $qb->setParameter('startDate', $startDate);
            $qb->andWhere("e.created <= :endDate");
            $qb->setParameter('endDate', $endDate);
        }

        if (!empty($toUser)) {
            $qb->join("e.toUser",'u');
            $qb->andWhere($qb->expr()->like("u.username", "'%$toUser%'" ));
        }

        if (!empty($user)) {
            $qb->join('e.createdBy','u');
            $qb->andWhere("u.id = :user")->setParameter('user', $user);
        }

        if (!empty($accountHead)) {
            $qb->andWhere("e.accountHead = :accountHead");
            $qb->setParameter('accountHead', $accountHead);
        }
        if (!empty($customer)) {
            $qb->andWhere("e.customer = :customer")->setParameter('customer', $customer);
        }
        if (!empty($vendor)) {
            $qb->andWhere("e.medicineVendor = :medicineVendor")->setParameter('medicineVendor', $vendor);
        }
        if (!empty($transactionMethod)) {
            $qb->andWhere("e.transactionMethod = :transactionMethod");
            $qb->setParameter('transactionMethod', $transactionMethod);
        }
        if (!empty($category)) {
            $qb->andWhere("e.expenseCategory = :category");
            $qb->setParameter('category', $category);
        }
        if (!empty($keyword)) {
            $qb->andWhere($qb->expr()->like("e.accountRefNo", "'%$keyword%'" ));
        }

    }

    public function apiExpense(GlobalOption $option , $data = array())
    {


        $dateSql = '';
        $categorySql = '';
        $keywordSql = '';
        $accountHeadSql = '';

        $startDate      = (isset($data['start_date']) and $data['start_date']) ? $data['start_date']:'';
        $endDate        = (isset($data['end_date']) and $data['end_date']) ? $data['end_date']:'';
        $toUser         = (isset($data['to_user_id']) and $data['to_user_id']) ? $data['to_user_id'] :'';
        $user           = (isset($data['user_id']) and $data['user_id'])? $data['user_id'] :'';
        $keyword        = (isset($data['keyword']) and $data['keyword']) ? $data['keyword'] :'';
        $accountHead    = (isset($data['account_head_id']) and $data['account_head_id']) ? $data['account_head_id'] :'';
        $category       = (isset($data['category_id']) and $data['category_id']) ? $data['category_id'] :'';

        if($startDate and $endDate){
            $dateSql =  "AND e.created BETWEEN '{$startDate}' AND '{$endDate}'";
        }
        if($keyword){
            $keywordSql =  "AND e.accountRefNo LIKE '%{$keyword}%'";
        }
        if($category){
            $categorySql =  "AND ec.id = {$category}";
        }
        if($accountHead){
            $accountHeadSql =  "AND ah.id = {$accountHead}";
        }

        $sql = "SELECT CAST(e.id AS UNSIGNED) AS id, e.accountRefNo AS invoice,  e.remark AS remark, CAST(e.amount AS DECIMAL(10, 2)) AS amount, ec.id AS category_id, ec.name AS category,ah.id AS account_head_id,ah.name AS account_head, u.id AS creatdBy_id, tu.username AS touser, u.username AS created_by,u.username AS created_by, u.username AS approved_by, DATE_FORMAT(e.created,'%d-%m-%Y') as created
        from Expenditure as e
        join fos_user  as tu ON  e.toUser_id = tu.id
        join fos_user  as u ON  e.createdBy_id = u.id
        join fos_user  as aub ON  e.approvedBy_id = aub.id
        join expenseCategory  as ec ON  e.expenseCategory_id = ec.id
        join account_head  as ah ON  ec.accountHead_id = ah.id
        where e.globalOption_id = :globalOption {$dateSql} {$keywordSql} {$categorySql} {$accountHeadSql} ORDER BY e.created DESC LIMIT 2000";
        $qb = $this->getEntityManager()->getConnection()->prepare($sql);
        $qb->bindValue('globalOption', $option->getId());
        $qb->execute();
        $result =  $qb->fetchAll();
        return $result;

    }

