    public function apiInsertExpense(GlobalOption $option, $item = array())
    {
        $em = $this->_em;
        $amount = (isset($item['amount']) and $item['amount'])? trim($item['amount']):0;
        $method = (isset($item['method_id']) and $item['method_id'])? $item['method_id']:'';
        $category = (isset($item['category_id']) and $item['category_id'])? $item['category_id']:'';
        $touser = (isset($item['toUser_id']) and $item['toUser_id'])? $item['toUser_id']:'';
        $createdBy = (isset($item['createdBy_id']) and $item['createdBy_id'])? $item['createdBy_id']:'';
        $description = (isset($item['remark']) and $item['remark'])? $item['remark']:'';

        $sales = new Expenditure();
        $sales->setGlobalOption($option);
        $sales->setAmount($amount);
        if($method){
            $bank = $em->getRepository('AccountingBundle:AccountBank')->find($method);
            $sales->setAccountBank($bank);
            $method = $em->getRepository('SettingToolBundle:TransactionMethod')->findOneBy(array('slug'=>'bank'));
            $sales->setTransactionMethod($method);
        }
        $category = $em->getRepository('AccountingBundle:ExpenseCategory')->find($category);
        if($category){
            $sales->setExpenseCategory($category);
            $sales->setAccountHead($sales->getExpenseCategory()->getAccountHead());
        }
        if($touser){
            $touser = $em->getRepository('UserBundle:User')->find($touser);
            $sales->setToUser($touser);
        }
        if($createdBy){
            $createdBy = $em->getRepository('UserBundle:User')->find($createdBy);
            $sales->setCreatedBy($createdBy);
        }
        $sales->setRemark($description);
        $sales->setProcess("In-progress");
        $em->persist($sales);
        $em->flush();

        return $entities = $this->apiExpense($option);

    }


